const normalize=(raw)=>{const d=raw||JSON.parse(JSON.stringify(seed));d.courses=Array.isArray(d.courses)?d.courses:[];d.classes=(d.classes||[]).map(c=>({...c,students:Number(c.students??0),subjects:Number(c.subjects??0),attendance:Number(c.attendance??0)}));d.students=d.students&&d.students.length?d.students:JSON.parse(JSON.stringify(defaultStudents));if(!d.students.some(x=>x.admissionNo===d.student.admissionNo))d.students.unshift({...defaultStudents[0],...d.student,id:'STU-DP1-1042',classId:'DP1'});d.attendanceRecords=d.attendanceRecords&&d.attendanceRecords.length?d.attendanceRecords:JSON.parse(JSON.stringify(defaultAttendanceRecords));d.academic=Array.isArray(d.academic)?d.academic:[];d.results=Array.isArray(d.results)?d.results:[];d.studentFees=d.studentFees&&typeof d.studentFees==='object'?d.studentFees:{};if(!d.feeModelVersion){d.students.forEach(st=>{const f=d.studentFees[st.id];if(f&&Number(f.total)===85000&&(!f.entries||!f.entries.length))f.total=0});d.feeModelVersion=2}d.students.forEach(st=>{if(!d.studentFees[st.id])d.studentFees[st.id]={total:0,entries:[],assigned:false};d.studentFees[st.id].total=Number(d.studentFees[st.id].total||0);d.studentFees[st.id].entries=Array.isArray(d.studentFees[st.id].entries)?d.studentFees[st.id].entries:[];if(typeof d.studentFees[st.id].assigned!=='boolean')d.studentFees[st.id].assigned=d.studentFees[st.id].total>0});const main=d.students.find(x=>x.admissionNo===d.student.admissionNo)||d.students[0];if(main&&!d.studentFees[main.id])d.studentFees[main.id]={total:0,entries:[],assigned:false};d.fees={total:Number(main?d.studentFees[main.id].total:0),entries:main?(d.studentFees[main.id].entries||[]):[]};d.fees.paid=d.fees.entries.reduce((a,x)=>a+Number(x.amount||0),0);return d};
const STORAGE_KEY='eduiq_v5_demo';const get=()=>normalize(JSON.parse(localStorage[STORAGE_KEY]||JSON.stringify(seed)));const save=d=>localStorage[STORAGE_KEY]=JSON.stringify(normalize(d));if(!localStorage[STORAGE_KEY])save(seed);
const state={view:'landing',student:!!sessionStorage.eduiqStudent,admin:!!sessionStorage.eduiqAdmin,page:'dashboard'};
const icon=(x)=>`<span class="icon">${x}</span>`;const money=n=>'₹'+Number(n).toLocaleString('en-IN');
const studentFee=(d,id)=>d.studentFees?.[id]||{total:0,entries:[],assigned:false};
const feePaid=(d,id)=>studentFee(d,id).entries.reduce((a,x)=>a+Number(x.amount||0),0);
const currentStudentRecord=(d)=>d.students.find(s=>s.admissionNo===d.student.admissionNo)||d.students[0];
function toast(m){const e=document.getElementById('toast');e.textContent=m;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2400)}
function landing(){return `<div class="landing"><nav class="landing-nav"><div class="logo"><span class="logo-mark">E</span><div><b>EduIQ</b><small>LMS</small></div></div><div class="nav-links"><a href="#features">Platform</a><a href="#insights">Insights</a><a href="#security">Security</a></div><button class="btn ghost" onclick="showLogin()">Student Login ${icon('→')}</button></nav><main><section class="hero"><div class="hero-copy"><div class="eyebrow light">THE ACADEMIC OPERATING SYSTEM</div><h1>Every part of student life.<br><em>One intelligent place.</em></h1><p>EduIQ LMS brings schedules, assignments, examinations, attendance, academic resources, fees and student records into one beautifully organized experience.</p><div class="hero-actions"><button class="btn primary xl" onclick="showLogin()">Enter EduIQ LMS ${icon('↗')}</button><button class="btn darkline xl" onclick="showLogin('admin')">Admin Portal</button></div><div class="trust"><span>●</span> Built for modern institutions <span>·</span> Secure role-based access <span>·</span> Supabase-ready</div></div><div class="hero-visual"><div class="orb orb-a"></div><div class="orb orb-b"></div><div class="dashboard-preview"><div class="preview-top"><span class="mini-logo">E</span><div><b>Good morning, Divyansh.</b><small>Monday · 5 October 2026</small></div><span class="preview-avatar">DV</span></div><div class="preview-stats"><div><small>Attendance</small><strong>87%</strong><i></i></div><div><small>Semester GPA</small><strong>8.6</strong><i></i></div><div><small>Fees recorded</small><strong>65%</strong><i></i></div></div><div class="preview-grid"><div class="mini-card"><div class="mini-head">Today's schedule <span>4 classes</span></div><div class="mini-line"><b>09:00</b><span>Pharmacology</span><em>NOW</em></div><div class="mini-line"><b>10:00</b><span>Pharmaceutics</span></div><div class="mini-line"><b>11:30</b><span>Human Anatomy</span></div></div><div class="mini-card fee-mini"><div class="mini-head">Fee status</div><div class="donut"><span>65%<small>deposited</small></span></div><small>₹55,000 of ₹85,000 recorded</small></div></div></div></div></section><section class="feature-strip" id="features"><div><span>01</span><b>One academic home</b><small>Everything students need today.</small></div><div><span>02</span><b>Admin control</b><small>Manage classes, records and fees.</small></div><div><span>03</span><b>Clear insights</b><small>Charts that explain progress instantly.</small></div><div><span>04</span><b>Mobile-first</b><small>Designed for real student routines.</small></div></section><section class="insight-section" id="insights"><div class="section-copy"><div class="eyebrow">DESIGNED AROUND DECISIONS</div><h2>See what matters<br>before it becomes a problem.</h2><p>Attendance thresholds, assignment pressure, examination dates and fee deposits are surfaced visually so students and administrators can act quickly.</p></div><div class="analytics-card"><div class="analytics-head"><div><small>Academic health</small><b>October overview</b></div><span class="trend">↗ 12.4%</span></div><div class="bars"><i style="height:42%"></i><i style="height:58%"></i><i style="height:51%"></i><i style="height:73%"></i><i style="height:66%"></i><i style="height:84%"></i><i style="height:91%"></i><i style="height:78%"></i><i style="height:96%"></i></div><div class="axis"><span>W1</span><span>W2</span><span>W3</span><span>W4</span></div></div></section><section class="security" id="security"><div class="security-box"><div><div class="eyebrow">TRUST BY DESIGN</div><h2>Institution-controlled access.<br>Student-owned profile details.</h2></div><p>Admission number and initial password are issued by the institution. Admin controls academic records; students can complete permitted personal information after their first login.</p></div></section></main><footer>© 2026 EduIQ LMS <span>Academic technology, thoughtfully designed.</span></footer></div>`}
function login(mode='student'){return `<div class="auth"><div class="auth-side"><div class="logo lightlogo"><span class="logo-mark">E</span><div><b>EduIQ</b><small>LMS</small></div></div><div><div class="eyebrow light">${mode==='admin'?'ADMIN CONSOLE':'STUDENT PORTAL'}</div><h1>${mode==='admin'?'Control the academic experience.':'Your academic life, beautifully organized.'}</h1><p>${mode==='admin'?'Manage students, classes, attendance, academics and offline fee records from one control center.':'Sign in with the Admission No. and password issued by your institution.'}</p></div><div class="auth-side-foot">Secure role-based access · Supabase-ready architecture</div></div><div class="auth-form"><button class="back" onclick="showLanding()">← Back to EduIQ</button><div class="form-card"><div class="eyebrow">${mode==='admin'?'ADMIN ACCESS':'STUDENT ACCESS'}</div><h2>${mode==='admin'?'Welcome back, Admin.':'Welcome back.'}</h2><p class="muted">${mode==='admin'?'Use the institution administrator credentials.':'Use the credentials provided by your institution.'}</p><form onsubmit="event.preventDefault();doLogin('${mode}')"><label>${mode==='admin'?'Admin ID':'Admission No.'}<input id="loginId" required value="${mode==='admin'?'admin':'EDUIQ-2026-1042'}" placeholder="e.g. EDUIQ-2026-1042"></label><label>Password<input id="loginPass" required type="password" value="${mode==='admin'?'EduIQ#Admin':'EduIQ@1042'}" placeholder="Enter password"></label><div class="form-row"><label class="check"><input type="checkbox"> Remember me</label><button type="button" class="linkbtn" onclick="toast('Please contact your institution administrator to reset credentials.')">Forgot password?</button></div><button class="btn primary full">${mode==='admin'?'Open Admin Portal':'Enter Student Portal'} ${icon('→')}</button></form><div class="login-note">${mode==='admin'?'Demo admin: admin / EduIQ#Admin':'Demo student: EDUIQ-2026-1042 / EduIQ@1042'}</div></div><div class="switch">${mode==='admin'?'Student?':'Institution admin?'} <button onclick="showLogin('${mode==='admin'?'student':'admin'}')">${mode==='admin'?'Student login':'Open admin portal'}</button></div></div></div>`}
function shell(admin=false){const studentNav=[['dashboard','Dashboard','⌂'],['schedule','Schedule','▦'],['assignments','Assignments','✓'],['homework','Homework','✎'],['calendar','Calendar','□'],['materials','Study Materials','▤'],['exams','Exams & Date Sheet','▣'],['results','Results','◒'],['attendance','Attendance','◔'],['fees','Fees','₹'],['notifications','Notifications','◌'],['profile','My Profile','◎']];const adminNav=[['admin','Overview','⌂'],['students','Students','♙'],['courses','Courses','◈'],['classes','Classes','▦'],['academics','Academics','◈'],['attendance','Attendance','◔'],['fees','Fees & Deposits','₹'],['announcements','Announcements','◉'],['reports','Reports','◒']];return `<div class="app"><aside class="side"><div class="brand"><span class="logo-mark">E</span><div><b>EduIQ</b><small>${admin?'Admin Console':'LMS'}</small></div></div>${admin?`<div class="side-section"><div class="side-label">OVERVIEW</div><nav>${adminNav.slice(0,1).map(x=>`<button class="nav ${state.page===x[0]?'active':''}" onclick="go('${x[0]}')">${icon(x[2])}<span>${x[1]}</span></button>`).join('')}</nav></div><div class="side-section section-divider"><div class="side-label">PEOPLE & STRUCTURE</div><nav>${adminNav.slice(1,5).map(x=>`<button class="nav ${state.page===x[0]?'active':''}" onclick="go('${x[0]}')">${icon(x[2])}<span>${x[1]}</span></button>`).join('')}</nav></div><div class="side-section section-divider"><div class="side-label">OPERATIONS</div><nav>${adminNav.slice(5).map(x=>`<button class="nav ${state.page===x[0]?'active':''}" onclick="go('${x[0]}')">${icon(x[2])}<span>${x[1]}</span></button>`).join('')}</nav></div>` :`<div class="side-label">WORKSPACE</div><nav>${studentNav.slice(0,5).map(x=>`<button class="nav ${state.page===x[0]?'active':''}" onclick="go('${x[0]}')">${icon(x[2])}<span>${x[1]}</span></button>`).join('')}</nav><div class="side-label section-divider">ACADEMICS</div><nav>${studentNav.slice(5,10).map(x=>`<button class="nav ${state.page===x[0]?'active':''}" onclick="go('${x[0]}')">${icon(x[2])}<span>${x[1]}</span></button>`).join('')}</nav><div class="side-label section-divider">ADMINISTRATION</div><nav>${studentNav.slice(10).map(x=>`<button class="nav ${state.page===x[0]?'active':''}" onclick="go('${x[0]}')">${icon(x[2])}<span>${x[1]}</span></button>`).join('')}</nav>`}<div class="side-bottom"><button class="nav" onclick="toggleTheme()">${icon('◐')}<span>Theme</span></button><button class="nav" onclick="logout()">${icon('↪')}<span>Sign out</span></button></div></aside><main class="main"><header class="top"><button class="mobile-menu" onclick="document.querySelector('.side').classList.toggle('open')">☰</button><div class="top-heading"><small>${admin?'ADMINISTRATION':'STUDENT PORTAL'}</small><b>${admin?'EduIQ Control Center':pageTitle()}</b></div><div class="top-right"><button class="circle" onclick="toggleTheme()">◐</button><button class="circle" onclick="go(admin?'announcements':'notifications')">◌</button><div class="top-user" onclick="go(admin?'admin':'profile')"><span>${admin?'AD':get().student.avatar}</span><div><b>${admin?'Administrator':get().student.name}</b><small>${admin?'Institution admin':get().student.admissionNo}</small></div></div></div></header><section class="main-content" id="screen"></section></main></div>`}
function pageTitle(){return ({dashboard:'Dashboard',schedule:'Schedule',assignments:'Assignments',homework:'Homework',calendar:'Calendar',materials:'Study Materials',exams:'Exams & Date Sheet',attendance:'Attendance',fees:'Fees',results:'Results',notifications:'Notifications',profile:'My Profile'})[state.page]||'Dashboard'}
function go(p){state.page=p;render();document.querySelector('.side')?.classList.remove('open')}
function studentScreen(){const d=get();const me=currentStudentRecord(d);const mf=studentFee(d,me.id);if(state.page==='homework')return resourcePage('Homework','Homework','Daily tasks assigned by your faculty.','Homework');if(state.page==='calendar')return resourcePage('Calendar','Calendar','Classes, exams, holidays and important deadlines.','Events & Calendar');if(state.page==='dashboard')return `<div class="welcome"><div><div class="eyebrow">MONDAY · 5 OCTOBER 2026</div><h1>Good evening, ${d.student.name.split(' ')[0]}.</h1><p>${d.student.course} · ${d.student.year} · ${d.student.roll}</p></div><button class="btn primary" onclick="go('profile')">Complete profile ${icon('→')}</button></div><div class="stats4"><div class="statcard"><small>Attendance</small><strong>${d.attendance.overall}%</strong><span class="positive">Good standing</span></div><div class="statcard"><small>Pending assignments</small><strong>04</strong><span class="warning">2 due this week</span></div><div class="statcard"><small>Semester GPA</small><strong>8.6</strong><span class="positive">Excellent</span></div><div class="statcard"><small>Fees deposited</small><strong>${Math.round(feePaid(d,me.id)/mf.total*100)}%</strong><span>${money(feePaid(d,me.id))} / ${money(mf.total)}</span></div></div><div class="dash-grid"><div class="panel"><div class="panel-title"><div><small>TODAY</small><h2>Schedule</h2></div><button class="linkbtn" onclick="go('schedule')">View all →</button></div><div class="timeline">${[['09:00','Pharmacology','Dr. Ananya Rao','NOW · Lecture'],['10:00','Pharmaceutics','Prof. K. Sharma','Lecture'],['11:30','Human Anatomy','Dr. Meera Singh','Practical'],['13:00','Biochemistry','Dr. Arjun Verma','Tutorial']].map((x,i)=>`<div class="tline ${i===0?'current':''}"><b>${x[0]}</b><i></i><div><strong>${x[1]}</strong><span>${x[2]} · Room ${204-i*18}</span></div><em>${x[3]}</em></div>`).join('')}</div></div><div class="panel"><div class="panel-title"><div><small>FINANCIAL OVERVIEW</small><h2>Fee deposit</h2></div><button class="linkbtn" onclick="go('fees')">Details →</button></div><div class="fee-chart"><div class="donut big" style="--p:${feePaid(d,me.id)/mf.total*100}%"><span>${Math.round(d.fees.paid/d.fees.total*100)}%<small>deposited</small></span></div><div><strong>${money(feePaid(d,me.id))}</strong><p>recorded of ${money(d.fees.total)}</p><span class="pill green">${money(mf.total-feePaid(d,me.id))} remaining</span></div></div><div class="mini-break"><span>Deposited <b>${money(d.fees.paid)}</b></span><span>Remaining <b>${money(mf.total-feePaid(d,me.id))}</b></span></div></div></div><div class="dash-grid"><div class="panel"><div class="panel-title"><div><small>ACADEMIC HEALTH</small><h2>Attendance by subject</h2></div><button class="linkbtn" onclick="go('attendance')">Full report →</button></div>${d.attendance.subjects.map(s=>`<div class="metric"><div><b>${s[0]}</b><span>${s[1]}%</span></div><div class="progress"><i style="width:${s[1]}%"></i></div></div>`).join('')}</div><div class="panel"><div class="panel-title"><div><small>UP NEXT</small><h2>Important</h2></div></div>${[['Internal assessment schedule published','Academic Office','2h ago'],['Pharmaceutics record due Friday','K. Sharma','Today'],['Fee installment due 15 Dec','Accounts Office','2 days']].map(x=>`<div class="notice"><span class="notice-dot">•</span><div><b>${x[0]}</b><small>${x[1]} · ${x[2]}</small></div></div>`).join('')}</div></div>`;
if(state.page==='fees')return feePage();if(state.page==='profile')return profilePage();if(state.page==='attendance')return attendancePage();if(state.page==='schedule')return schedulePage();if(state.page==='results')return resultsPage();if(state.page==='assignments')return resourcePage('Assignments','Assignments','Track submissions, deadlines and faculty feedback.','Assignments');if(state.page==='exams')return resourcePage('Exams & Date Sheet','Exams & Date Sheet','Upcoming assessments and published examination documents.','Exams & Date Sheets');if(state.page==='materials')return resourcePage('Study Materials','Study Materials','Your institution-curated academic library.','Study Materials');if(state.page==='notifications')return tablePage('Notifications','Academic events and reminders.',['Notification','Category','Time','Status'],[['Assignment due tomorrow','Assignment','10 min ago','Unread'],['New exam schedule published','Examination','2 hr ago','Unread'],['Attendance report updated','Attendance','Yesterday','Read'],['Fee installment reminder','Fees','2 days ago','Read']]);return `<div class="empty panel"><div class="empty-icon">◎</div><h2>${pageTitle()}</h2><p>This module is ready for Supabase-backed records in the next integration stage.</p></div>`}
function tablePage(t,s,h,r){return `<div class="page-head"><div><div class="eyebrow">STUDENT ACADEMICS</div><h1>${t}</h1><p>${s}</p></div></div><div class="panel table-panel"><table><thead><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${r.map(row=>`<tr>${row.map((x,i)=>`<td>${i===row.length-1?`<span class="pill ${/Submitted|Paid|Read|Graded/.test(x)?'green':/In progress|Unread/.test(x)?'blue':'amber'}">${x}</span>`:x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function feePage(){const d=get(),me=currentStudentRecord(d),f=studentFee(d,me.id),paid=feePaid(d,me.id),pct=f.total?paid/f.total*100:0;return `<div class="page-head"><div><div class="eyebrow">FINANCE</div><h1>Fee center</h1><p>Your course fee is assigned by the institution. Only recorded offline deposits appear here.</p></div></div><div class="fee-overview"><div class="panel fee-main"><div class="donut huge" style="--p:${pct}%"><span>${Math.round(pct)}%<small>deposited</small></span></div><div><small>TOTAL COURSE FEE</small><h2>${money(f.total)}</h2><p><b>${money(paid)}</b> deposited · <b>${money(f.total-paid)}</b> remaining</p><div class="progress wide"><i style="width:${pct}%"></i></div></div></div><div class="panel"><small>COURSE</small><h2>${me.course}</h2><p>${me.year}</p><span class="pill green">Institution maintained</span></div></div><div class="panel table-panel"><div class="panel-title"><div><small>OFFLINE RECORDS</small><h2>Payment history</h2></div><span class="pill green">Admin maintained</span></div><table><thead><tr><th>Date</th><th>Receipt ID</th><th>Amount</th><th>Method</th><th>Status</th></tr></thead><tbody>${(f.entries||[]).map(x=>`<tr><td>${x.date}</td><td>${x.id}</td><td><b>${money(x.amount)}</b></td><td>${x.method}</td><td><span class="pill green">Recorded</span></td></tr>`).join('')||`<tr><td colspan="5"><div class="empty"><h2>No deposits recorded</h2><p>Ask the accounts office to record your offline deposit.</p></div></td></tr>`}</tbody></table></div>`}
function profilePage(){const s=get().student;return `<div class="page-head"><div><div class="eyebrow">STUDENT PROFILE</div><h1>My profile</h1><p>Academic identity is controlled by the institution. You can complete permitted personal details.</p></div></div><div class="profile-grid"><div class="panel identity"><div class="profile-avatar">${s.avatar}</div><h2>${s.name}</h2><p>${s.course} · ${s.year}</p><span class="pill blue">Admission ${s.admissionNo}</span><div class="identity-list"><span>Roll number <b>${s.roll}</b></span><span>Session <b>${s.session}</b></span><span>Date of birth <b>${s.dob}</b></span></div></div><div class="panel"><div class="panel-title"><div><small>PERSONAL DETAILS</small><h2>Complete your profile</h2></div><span class="pill green">Admin verified identity</span></div><form onsubmit="saveProfile(event)"><div class="form-grid"><label>Full name<input id="pname" value="${s.name}" disabled></label><label>Admission No.<input value="${s.admissionNo}" disabled></label><label>Phone number<input id="pphone" value="${s.phone||''}" placeholder="+91 98XXXXXXXX"></label><label>Email address<input id="pemail" value="${s.email||''}" type="email" placeholder="you@example.com"></label><label>Guardian name<input id="pguardian" value="${s.guardian||''}" placeholder="Parent / guardian"></label><label>Address<input id="paddress" value="${s.address||''}" placeholder="Residential address"></label></div><button class="btn primary">Save personal details ${icon('✓')}</button></form></div></div>`}
function saveProfile(e){e.preventDefault();const d=get();Object.assign(d.student,{phone:pphone.value,email:pemail.value,guardian:pguardian.value,address:paddress.value});save(d);toast('Profile details saved locally. Supabase can persist them after integration.');go('profile')}
function attendancePage(){const d=get();return `<div class="page-head"><div><div class="eyebrow">ACADEMIC HEALTH</div><h1>Attendance</h1><p>Stay above the required threshold.</p></div></div><div class="attendance-head panel"><div class="donut big" style="--p:${d.attendance.overall}%"><span>${d.attendance.overall}%<small>overall</small></span></div><div><small>STATUS</small><h2>Good standing</h2><p>Required minimum: 75%</p></div></div><div class="subject-grid">${d.attendance.subjects.map(x=>`<div class="panel metric-card"><div><b>${x[0]}</b><strong>${x[1]}%</strong></div><div class="progress"><i style="width:${x[1]}%"></i></div><small>${x[1]>=85?'Healthy attendance':'Approaching threshold'}</small></div>`).join('')}</div>`}
function schedulePage(){const d=get(),sid=((d.students||[]).find(s=>s.admissionNo===d.student.admissionNo)||{}).classId||'DP1',items=(d.academic||[]).filter(x=>x.type==='Timetable'&&(x.status==='Published'||!x.status)&&(x.classId===sid||!x.classId));return `<div class="page-head"><div><div class="eyebrow">WEEKLY RHYTHM</div><h1>Schedule</h1><p>Classes, practicals and tutorials.</p></div></div><div class="panel table-panel"><table><thead><tr><th>Time</th><th>Monday</th><th>Tuesday</th><th>Wednesday</th><th>Thursday</th><th>Friday</th></tr></thead><tbody>${[['09:00','Pharmacology','Pharmaceutics','Pharmacology','Biochemistry','Pharmacology'],['10:00','Pharmaceutics','Anatomy','Break','Pharmaceutics','Biochemistry'],['11:30','Human Anatomy','Pharmaceutics Lab','Human Anatomy','Practical','Human Anatomy'],['13:00','Biochemistry','—','Biochemistry','Tutorial','Biochemistry']].map(r=>`<tr>${r.map((x,i)=>`<td>${i?`<span class="pill ${x==='Break'?'amber':'blue'}">${x}</span>`:x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${items.length?`<div class="panel resource-strip"><div class="panel-title"><div><small>PUBLISHED FILES</small><h2>Timetable documents</h2></div></div><div class="resource-inline">${items.map(resourceCard).join('')}</div></div>`:''}`}
function resultsPage(){const d=get(),mine=(d.results||[]).filter(r=>r.studentId===((d.students||[]).find(s=>s.admissionNo===d.student.admissionNo)||{}).id);const rows=mine.length?mine.map(r=>[r.subject,String(r.max),String(r.obtained),r.grade,String(r.point)]):[['Pharmaceutics','100','88','A','9'],['Pharmacology','100','91','A+','10'],['Human Anatomy','100','84','A','9'],['Biochemistry','100','82','A','9'],['Practical','100','93','A+','10']];return `<div class="page-head"><div><div class="eyebrow">PERFORMANCE</div><h1>Results</h1><p>Semester performance at a glance.</p></div></div><div class="result-top panel"><div class="donut big" style="--p:86.2%"><span>8.6<small>SGPA</small></span></div><div><small>SEMESTER I</small><h2>86.2%</h2><p>${mine.length?'Admin-published results':'Demo academic result'} · Excellent standing</p></div></div>${tablePage('', '', ['Subject','Maximum','Obtained','Grade','Grade Point'],rows)}`}
function simpleStudentPage(kicker,title,desc,items){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div></div><div class="subject-grid">${items.map((x,i)=>`<div class="panel metric-card"><div><b>${x}</b><span class="pill ${i===0?'blue':'green'}">${i===0?'Upcoming':'Scheduled'}</span></div><p class="muted">Class feed managed by your institution.</p><button class="linkbtn" onclick="toast('This item will open from your class feed.')">View details →</button></div>`).join('')}</div>`}
function resourcePage(kicker,title,desc,type){const d=get(),sid=((d.students||[]).find(s=>s.admissionNo===d.student.admissionNo)||{}).classId||'DP1',items=(d.academic||[]).filter(x=>x.type===type&&(x.status==='Published'||!x.status)&&(x.classId===sid||!x.classId));return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div></div><div class="resource-grid">${items.length?items.map(resourceCard).join(''):`<div class="panel empty"><div class="empty-icon">▤</div><h2>No published ${title.toLowerCase()} yet.</h2><p>Your institution will publish content here.</p></div>`}</div>`}
function resourceCard(x){const a=x.attachment;return `<article class="panel resource-card"><div class="resource-meta"><span class="pill blue">${x.type}</span><span>${new Date(x.createdAt||Date.now()).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})}</span></div><h2>${x.title}</h2><p>${x.details||'Published by your institution.'}</p>${a?(a.type.startsWith('image/')?`<img class="resource-image" src="${a.data}" alt="${a.name}">`:`<div class="file-preview"><span>PDF</span><b>${a.name}</b><small>${(a.size/1024/1024).toFixed(2)} MB</small></div><div class="resource-actions"><button class="btn" onclick="viewAttachment(${x.id})">View</button><button class="btn primary" onclick="downloadAttachment(${x.id})">Download</button></div>`):''}${a&&a.type.startsWith('image/')?`<div class="resource-actions"><button class="btn" onclick="viewAttachment(${x.id})">View image</button><button class="btn primary" onclick="downloadAttachment(${x.id})">Download image</button></div>`:''}</article>`}
function viewAttachment(id){const d=get(),x=d.academic.find(a=>a.id===id);if(!x?.attachment)return;const a=x.attachment;if(a.type.startsWith('image/'))document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">ATTACHMENT PREVIEW</div><h2>${a.name}</h2><img class="attachment-preview" src="${a.data}" alt="${a.name}"><div class="modal-actions"><button class="btn" onclick="document.getElementById('modal').remove()">Close</button><button class="btn primary" onclick="downloadAttachment(${id})">Download</button></div></div></div>`);else window.open(a.data,'_blank','noopener')}
function downloadAttachment(id){const d=get(),x=d.academic.find(a=>a.id===id);if(!x?.attachment)return;const a=x.attachment;const link=document.createElement('a');link.href=a.data;link.download=a.name;document.body.appendChild(link);link.click();link.remove()}

function adminScreen(){const d=get();if(state.page==='admin')return `<div class="welcome"><div><div class="eyebrow">INSTITUTION OVERVIEW</div><h1>Control center.</h1><p>Manage students, classes, academic records and offline fee deposits.</p></div><button class="btn primary" onclick="go('students')">Add student ${icon('+')}</button></div><div class="stats4"><div class="statcard"><small>Total students</small><strong>248</strong><span class="positive">+14 this session</span></div><div class="statcard"><small>Active classes</small><strong>12</strong><span>Across 4 departments</span></div><div class="statcard"><small>Fee collection</small><strong>₹42.8L</strong><span class="positive">81% recorded</span></div><div class="statcard"><small>Attendance</small><strong>86%</strong><span class="positive">Institution average</span></div></div><div class="admin-grid"><div class="panel"><div class="panel-title"><div><small>FEE COLLECTION</small><h2>Monthly deposits</h2></div><span class="trend">↗ 8.2%</span></div><div class="admin-bars">${[48,61,54,72,66,81,74,91,82,96].map((x,i)=>`<i style="height:${x}%"><span>${i+1}</span></i>`).join('')}</div></div><div class="panel"><div class="panel-title"><div><small>CLASS HEALTH</small><h2>Attendance distribution</h2></div></div><div class="ring-list"><div class="donut big" style="--p:86%"><span>86%<small>average</small></span></div><div><p><b>168</b> students above 85%</p><p><b>62</b> between 75–85%</p><p><b>18</b> need attention</p></div></div></div></div>`;if(state.page==='students')return adminStudents();if(state.page==='courses')return adminCourses();if(state.page==='classes')return adminClasses();if(state.page==='fees')return adminFees();if(state.page==='academics')return adminAcademics();if(state.page==='attendance')return adminAttendance();if(state.page==='reports')return `<div class="page-head"><div><div class="eyebrow">REPORTING</div><h1>Reports</h1><p>Operational insights for institutional decisions.</p></div></div><div class="admin-grid"><div class="panel"><h2>Academic performance</h2><div class="admin-bars tall">${[72,78,82,75,88,91,86].map((x,i)=>`<i style="height:${x}%"><span>${['P','Ph','A','B','C','D','E'][i]}</span></i>`).join('')}</div></div><div class="panel"><h2>Quick exports</h2><div class="quick-actions"><button class="btn" onclick="toast('CSV export will connect to Supabase.')">Export students CSV</button><button class="btn" onclick="toast('PDF report will connect to Supabase.')">Generate fee report</button><button class="btn" onclick="toast('Attendance export will connect to Supabase.')">Attendance report</button></div></div></div>`;return tablePage('Announcements','Publish institutional communication.',['Title','Category','Audience','Status'],[['Internal assessment schedule published','Academic','D.Pharm','Published'],['Library extended hours','Notice','All students','Published'],['Scholarship renewal window','Fees','Eligible students','Draft']])}
function adminStudents(){const d=get();const rows=(d.students||[]).map(x=>{const f=studentFee(d,x.id),paid=feePaid(d,x.id),total=Number(f.total||0);return `<tr><td><b>${x.name}</b><small class="cell-sub">${x.roll||'—'}</small></td><td>${x.admissionNo}</td><td>${x.course} · ${x.year}</td><td>${money(paid)} / ${money(total)}</td><td><span class="pill green">Active</span></td><td><button class="linkbtn" onclick="openStudentModal('${x.id}')">Edit</button><button class="danger-link inline" onclick="deleteStudent('${x.id}')">Delete</button></td></tr>`}).join('');return `<div class="page-head"><div><div class="eyebrow">STUDENT DIRECTORY</div><h1>Students</h1><p>Create institution-issued credentials and manage academic identity.</p></div><button class="btn primary" onclick="openStudentModal()">+ Add student</button></div><div class="panel table-panel"><table><thead><tr><th>Student</th><th>Admission No.</th><th>Class</th><th>Course fee / Paid</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows}</tbody></table></div>`}
function openStudentModal(editId=''){const d=get(),existing=editId?(d.students||[]).find(x=>x.id===editId):null;const fee=existing?studentFee(d,existing.id):{total:0,entries:[],assigned:false};const courseId=existing?.courseId||'';const course=courseId?d.courses.find(c=>c.id===courseId):null;document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">${existing?'EDIT STUDENT':'NEW STUDENT'}</div><h2>${existing?'Update academic identity':'Issue portal access'}</h2><p class="muted">Choose the master course first. Its configured fee becomes the student's default course fee; you can override the individual fee when required.</p><form onsubmit="event.preventDefault();saveStudent('${editId}')"><div class="form-grid"><label>Student name<input id="sname" required value="${existing?.name||''}" placeholder="Full name"></label><label>Admission No.<input id="sadmission" required value="${existing?.admissionNo||'EDUIQ-2026-1050'}"></label><label>Initial password<input id="spassword" required value="${existing?.password||'EduIQ@1050'}"></label><label>Course<select id="scourse" onchange="updateStudentCourseDefaults()"><option value="">Select course</option>${(d.courses||[]).map(c=>`<option value="${c.id}" ${courseId===c.id?'selected':''}>${c.name} · ${money(c.fee||0)}</option>`).join('')}</select></label><label>Class<select id="sclass">${(d.classes||[]).filter(c=>!courseId||c.courseId===courseId).map(c=>`<option value="${c.id}" ${(existing?.classId||'')===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label><label>Roll number<input id="sroll" value="${existing?.roll||'24DP1050'}"></label><label>Assigned course fee<input id="scoursefee" type="number" min="0" required value="${Number(fee.total||course?.fee||0)}" placeholder="Course fee"><small class="field-hint">Defaults from the selected course. Admin may override for an individual student.</small></label></div><div class="modal-actions"><button type="button" class="btn" onclick="document.getElementById('modal').remove()">Cancel</button><button class="btn primary">${existing?'Save changes':'Create & issue access'}</button></div></form></div></div>`)}
function updateStudentCourseDefaults(){const d=get(),cid=document.getElementById('scourse').value,c=d.courses.find(x=>x.id===cid);const fee=document.getElementById('scoursefee');if(c)fee.value=Number(c.fee||0);const sel=document.getElementById('sclass');sel.innerHTML=(d.classes||[]).filter(x=>x.courseId===cid).map(x=>`<option value="${x.id}">${x.name}</option>`).join('');}
function saveStudent(editId){const d=get(),id=editId||('STU-'+Date.now()),classId=document.getElementById('sclass').value,courseId=document.getElementById('scourse').value,course=d.courses.find(c=>c.id===courseId),student={id,name:document.getElementById('sname').value.trim(),admissionNo:document.getElementById('sadmission').value.trim(),password:document.getElementById('spassword').value,course:course?.name||'',courseId,year:(d.classes.find(c=>c.id===classId)?.name||'').replace(/^.*—\s*/,'')||'First Year',classId,roll:document.getElementById('sroll').value.trim()};if(!courseId)return toast('Select a course before creating or assigning the student.');if(!classId)return toast('Assign the student to a class under the selected course.');if(editId){const i=d.students.findIndex(x=>x.id===editId);if(i>=0){const oldClass=d.students[i].classId;d.students[i]={...d.students[i],...student};if(oldClass!==classId){const oldC=d.classes.find(c=>c.id===oldClass),newC=d.classes.find(c=>c.id===classId);if(oldC)oldC.students=Math.max(0,Number(oldC.students||0)-1);if(newC)newC.students=Number(newC.students||0)+1;}}}else{d.students.push(student);const cls=d.classes.find(c=>c.id===classId);if(cls)cls.students=Number(cls.students||0)+1;d.attendanceRecords=d.attendanceRecords||[];d.attendanceRecords.push({studentId:id,studentName:student.name,admissionNo:student.admissionNo,classId,courseId,subjects:[],overall:0});}d.studentFees=d.studentFees||{};d.studentFees[id]=d.studentFees[id]||{total:0,entries:[],assigned:false};d.studentFees[id].total=Number(document.getElementById('scoursefee').value||0);d.studentFees[id].courseId=courseId;d.studentFees[id].assigned=d.studentFees[id].total>0;save(d);document.getElementById('modal')?.remove();toast(editId?'Student updated.':'Student created and assigned to course.');go('students')}
function deleteStudent(id){const d=get(),st=d.students.find(x=>x.id===id);if(!st)return;if(!confirm(`Delete ${st.name} (${st.admissionNo})? This removes the student from the local demo, including attendance, results and fee records.`))return;const cls=d.classes.find(c=>c.id===st.classId);if(cls)cls.students=Math.max(0,Number(cls.students||0)-1);d.students=d.students.filter(x=>x.id!==id);delete d.studentFees?.[id];d.attendanceRecords=(d.attendanceRecords||[]).filter(x=>x.studentId!==id);d.results=(d.results||[]).filter(x=>x.studentId!==id);save(d);toast('Student deleted.');go('students')}
function adminCourses(){const d=get(),courses=d.courses||[];return `<div class="page-head"><div><div class="eyebrow">ACADEMIC CATALOG</div><h1>Courses</h1><p>Create the master course first, define its fee and academic details, then attach classes and students to it.</p></div><button class="btn primary" onclick="openCourseModal()">+ Create course</button></div><div class="class-grid">${courses.length?courses.map(c=>{const cls=(d.classes||[]).filter(x=>x.courseId===c.id),sts=(d.students||[]).filter(x=>x.courseId===c.id),recs=(d.attendanceRecords||[]).filter(r=>sts.some(s=>s.id===r.studentId));const att=recs.length?Math.round(recs.reduce((a,r)=>a+Number(r.overall||0),0)/recs.length):0;return `<div class="panel class-card"><span class="class-icon">◈</span><div class="course-code">${c.code||'COURSE'}</div><h2>${c.name}</h2><p class="muted">${c.description||'No course description yet.'}</p><div><b>${money(c.fee||0)} fee</b><span>${cls.length} classes</span><span>${sts.length} students</span><span>${att}% attendance</span></div><div class="class-actions"><button class="linkbtn" onclick="openCourseManager('${c.id}')">Manage course →</button><button class="danger-link" onclick="deleteCourse('${c.id}')">Delete course</button></div></div>`}).join(''):`<div class="panel empty"><div class="empty-icon">◈</div><h2>No courses created</h2><p>Create a course with its details and fee before assigning classes or students.</p><button class="btn primary" onclick="openCourseModal()">Create your first course</button></div>`}</div>`}
function openCourseModal(editId=''){const d=get(),c=editId?(d.courses||[]).find(x=>x.id===editId):null;document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">${c?'EDIT COURSE':'NEW COURSE'}</div><h2>${c?'Update course details':'Create course'}</h2><p class="muted">Define the academic program first. Its fee becomes the default fee when students are assigned to this course.</p><form onsubmit="event.preventDefault();saveCourse('${editId}')"><div class="form-grid"><label>Course name<input id="courseName" required value="${c?.name||''}" placeholder="D.Pharm"></label><label>Course code<input id="courseCode" value="${c?.code||''}" placeholder="DPHARM"></label><label>Course fee<input id="courseFee" type="number" min="0" required value="${c?.fee??0}" placeholder="85000"></label><label>Duration<input id="courseDuration" value="${c?.duration||''}" placeholder="2 Years"></label><label>Academic session<input id="courseSession" value="${c?.session||'2026–27'}" placeholder="2026–27"></label><label>Status<select id="courseStatus"><option ${c?.status==='inactive'?'':'selected'}>Active</option><option ${c?.status==='inactive'?'selected':''}>Inactive</option></select></label><label class="full">Description<textarea id="courseDescription" rows="4" placeholder="Course overview, eligibility, structure...">${c?.description||''}</textarea></label></div><div class="modal-actions"><button type="button" class="btn" onclick="document.getElementById('modal').remove()">Cancel</button><button class="btn primary">${c?'Save changes':'Create course'}</button></div></form></div></div>`)}
function saveCourse(editId){const d=get(),id=editId||'COURSE-'+Date.now(),course={id,name:document.getElementById('courseName').value.trim(),code:document.getElementById('courseCode').value.trim(),fee:Number(document.getElementById('courseFee').value||0),duration:document.getElementById('courseDuration').value.trim(),session:document.getElementById('courseSession').value.trim(),status:document.getElementById('courseStatus').value,description:document.getElementById('courseDescription').value.trim()};if(!course.name)return toast('Course name is required.');if(editId){const i=d.courses.findIndex(x=>x.id===editId);if(i>=0)d.courses[i]={...d.courses[i],...course}}else d.courses.push(course);save(d);document.getElementById('modal')?.remove();toast(editId?'Course updated.':'Course created successfully.');go('courses')}
function openCourseManager(id){const d=get(),c=d.courses.find(x=>x.id===id);if(!c)return;const classes=d.classes.filter(x=>x.courseId===id),students=d.students.filter(x=>x.courseId===id),recs=d.attendanceRecords.filter(r=>students.some(s=>s.id===r.studentId)),att=recs.length?Math.round(recs.reduce((a,r)=>a+Number(r.overall||0),0)/recs.length):0;document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">COURSE MANAGEMENT</div><h2>${c.name}</h2><p class="muted">${c.code||''} · ${c.duration||'Duration not set'} · Course fee ${money(c.fee||0)}</p><div class="course-overview-grid"><div class="panel"><small>CLASSES</small><strong>${classes.length}</strong><span>Assigned class groups</span></div><div class="panel"><small>STUDENTS</small><strong>${students.length}</strong><span>Currently enrolled</span></div><div class="panel"><small>OVERALL ATTENDANCE</small><strong>${att}%</strong><span>Across this course</span></div></div><div class="course-class-list"><h3>Classes assigned to this course</h3>${classes.length?classes.map(x=>`<div class="course-class-row"><div><b>${x.name}</b><span>${x.students||0} students</span></div><strong>${Number(x.attendance||0)}%</strong><button class="linkbtn" onclick="openAttendanceRoster('${x.id}')">Attendance</button></div>`).join(''):`<div class="empty compact"><p>No classes assigned. Edit/create a class and choose this course.</p></div>`}</div><div class="modal-actions"><button class="btn" onclick="document.getElementById('modal').remove()">Close</button><button class="btn" onclick="openCourseEdit('${id}')">Edit course</button><button class="btn primary" onclick="document.getElementById('modal').remove();openClassModal('${id}')">+ Assign class</button></div></div></div>`)}
function openCourseEdit(id){document.getElementById('modal')?.remove();openCourseModal(id)}
function deleteCourse(id){const d=get(),c=d.courses.find(x=>x.id===id);if(!c)return;const usedStudents=d.students.some(s=>s.courseId===id),usedClasses=d.classes.some(x=>x.courseId===id);if(usedStudents||usedClasses)return toast('This course is assigned to students or classes. Reassign them before deleting the course.');if(!confirm(`Delete course ${c.name}?`))return;d.courses=d.courses.filter(x=>x.id!==id);save(d);toast('Course deleted.');go('courses')}

function adminClasses(){const d=get(),classes=d.classes||[];return `<div class="page-head"><div><div class="eyebrow">ACADEMIC STRUCTURE</div><h1>Classes</h1><p>Create class groups under a course. Attendance is tracked through students assigned to each class.</p></div><button class="btn primary" onclick="openClassModal()">+ Create class</button></div><div class="class-grid">${classes.map(x=>{const course=d.courses.find(c=>c.id===x.courseId);return `<div class="panel class-card"><span class="class-icon">▦</span><div class="course-code">${course?.code||'UNASSIGNED COURSE'}</div><h2>${x.name}</h2><div><b>${x.students??0} students</b><span>${x.subjects??0} subjects</span><span>${x.attendance??0}% attendance</span></div><div class="class-actions"><button class="linkbtn" onclick="openClassManager('${x.id}')">Manage class →</button><button class="danger-link" onclick="deleteClass('${x.id}')">Delete class</button></div></div>`}).join('')}</div>`}
function openClassManager(id){const d=get(),c=(d.classes||[]).find(x=>x.id===id);if(!c)return;document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">CLASS MANAGEMENT</div><h2>${c.name}</h2><p class="muted">${c.students??0} students · ${c.subjects??0} subjects · ${c.attendance??0}% attendance</p><div class="manager-grid"><button class="manager-item" onclick="openRoster('${c.id}')"><strong>Students</strong><span>View / edit class roster</span><b>Open →</b></button><button class="manager-item" onclick="openAcademicEditor('Subjects','${c.id}')"><strong>Subjects</strong><span>Add or remove subjects</span><b>Open →</b></button><button class="manager-item" onclick="openAcademicEditor('Timetable','${c.id}')"><strong>Timetable</strong><span>Assign weekly periods</span><b>Open →</b></button><button class="manager-item" onclick="openAcademicEditor('Assignments','${c.id}')"><strong>Assignments</strong><span>Publish class assignments</span><b>Open →</b></button><button class="manager-item" onclick="openAcademicEditor('Homework','${c.id}')"><strong>Homework</strong><span>Send daily class work</span><b>Open →</b></button><button class="manager-item" onclick="openAcademicEditor('Exams & Date Sheets','${c.id}')"><strong>Exams & Date Sheet</strong><span>Create examinations</span><b>Open →</b></button><button class="manager-item" onclick="openAcademicEditor('Study Materials','${c.id}')"><strong>Study Materials</strong><span>Upload class resources</span><b>Open →</b></button><button class="manager-item" onclick="openAcademicEditor('Results','${c.id}')"><strong>Results</strong><span>Enter student results</span><b>Open →</b></button><button class="manager-item" onclick="openAcademicEditor('Announcements','${c.id}')"><strong>Announcements</strong><span>Publish class notices</span><b>Open →</b></button><button class="manager-item" onclick="openAcademicEditor('Events & Calendar','${c.id}')"><strong>Events & Calendar</strong><span>Create class events</span><b>Open →</b></button></div><div class="modal-actions"><button class="btn danger" onclick="deleteClass('${c.id}')">Delete class</button><button class="btn" onclick="document.getElementById('modal').remove()">Close</button><button class="btn primary" onclick="openClassEdit('${c.id}')">Edit class</button></div></div></div>`)}
function openRoster(id){const d=get();const c=(d.classes||[]).find(x=>x.id===id);document.getElementById('modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">CLASS ROSTER</div><h2>${c.name}</h2><div class="roster-list"><div><b>${d.student.name}</b><span>${d.student.admissionNo}</span><em>Active</em></div><div><b>Ananya Singh</b><span>EDUIQ-2026-1011</span><em>Active</em></div><div><b>Rahul Sharma</b><span>EDUIQ-2026-1018</span><em>Active</em></div></div><div class="modal-actions"><button class="btn" onclick="document.getElementById('modal').remove()">Close</button></div></div></div>`)}
function openClassEdit(id){const d=get();const c=(d.classes||[]).find(x=>x.id===id);document.getElementById('modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">EDIT CLASS</div><h2>Update class</h2><form onsubmit="event.preventDefault();const d=get();const c=d.classes.find(x=>x.id==='${id}');c.name=document.getElementById('cname').value;c.courseId=document.getElementById('ccourse').value;c.students=Number(document.getElementById('cstudents').value);c.subjects=Number(document.getElementById('csubjects').value);c.attendance=Number(document.getElementById('cattendance').value);save(d);document.getElementById('modal').remove();toast('Class updated successfully.');go('classes')"><div class="form-grid"><label>Course<select id="ccourse"><option value="">Unassigned</option>${(d.courses||[]).map(x=>`<option value="${x.id}" ${c.courseId===x.id?'selected':''}>${x.name} · ${money(x.fee||0)}</option>`).join('')}</select></label><label>Class name<input id="cname" value="${c.name}"></label><label>Students<input id="cstudents" type="number" value="${c.students}"></label><label>Subjects<input id="csubjects" type="number" value="${c.subjects}"></label><label>Attendance %<input id="cattendance" type="number" min="0" max="100" value="${c.attendance}"></label></div><div class="modal-actions"><button type="button" class="btn" onclick="document.getElementById('modal').remove()">Cancel</button><button class="btn primary">Save changes</button></div></form></div></div>`)}
function openClassModal(courseId=''){const d=get();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">NEW CLASS</div><h2>Create class</h2><form onsubmit="event.preventDefault();const d=get();d.classes=d.classes||[];const cid=document.getElementById('newclasscourse').value;d.classes.push({id:'CLS'+Date.now(),name:document.getElementById('newclass').value,courseId:cid||null,students:0,subjects:0,attendance:0});save(d);document.getElementById('modal').remove();toast('Class created and linked to the selected course.');go('classes')"><label>Course<select id="newclasscourse"><option value="">Unassigned</option>${(d.courses||[]).map(c=>`<option value="${c.id}" ${courseId===c.id?'selected':''}>${c.name} · ${money(c.fee||0)}</option>`).join('')}</select><small class="field-hint">Create a course first if this class belongs to a program.</small></label><label>Class name<input id="newclass" required placeholder="D.Pharm — First Year"></label><div class="modal-actions"><button type="button" class="btn" onclick="document.getElementById('modal').remove()">Cancel</button><button class="btn primary">Create class</button></div></form></div></div>`)}
function deleteClass(id){const d=get(),c=(d.classes||[]).find(x=>x.id===id);if(!c)return;if(!confirm(`Delete ${c.name}? This removes the class and its local demo academic feed. Continue?`))return;d.classes=d.classes.filter(x=>x.id!==id);d.students=(d.students||[]).map(s=>s.classId===id?{...s,classId:''}:s);d.attendanceRecords=(d.attendanceRecords||[]).filter(x=>x.classId!==id);d.academic=(d.academic||[]).filter(x=>x.classId!==id);d.results=(d.results||[]).filter(x=>x.classId!==id);document.getElementById('modal')?.remove();save(d);toast('Class deleted.');go('classes')}

function adminFees(){const d=get();const allEntries=Object.entries(d.studentFees||{}).flatMap(([studentId,f])=>(f.entries||[]).map(e=>({...e,studentId})));const total=(d.students||[]).reduce((a,s)=>a+Number(studentFee(d,s.id).total||0),0),paid=allEntries.reduce((a,x)=>a+Number(x.amount||0),0),out=Math.max(total-paid,0),pct=total?paid/total*100:0;return `<div class="page-head"><div><div class="eyebrow">OFFLINE ACCOUNTS</div><h1>Fees & deposits</h1><p>Every student has an individually assigned course fee. Record offline deposits against that student.</p></div><button class="btn primary" onclick="openFeeModal()">+ Record deposit</button></div><div class="stats4"><div class="statcard"><small>Total billed</small><strong>${money(total)}</strong><span>${d.students.length} students</span></div><div class="statcard"><small>Recorded</small><strong>${money(paid)}</strong><span class="positive">${Math.round(pct)}%</span></div><div class="statcard"><small>Outstanding</small><strong>${money(out)}</strong><span class="warning">${Math.round(Math.max(100-pct,0))}%</span></div><div class="statcard"><small>Receipts</small><strong>${allEntries.length}</strong><span>Recorded offline</span></div></div><div class="panel table-panel"><table><thead><tr><th>Student</th><th>Course fee</th><th>Paid</th><th>Receipt</th><th>Amount</th><th>Method</th><th>Date</th><th>Actions</th></tr></thead><tbody>${allEntries.length?allEntries.map(x=>{const st=d.students.find(s=>s.id===x.studentId);const f=studentFee(d,x.studentId);return `<tr><td>${st?.name||'Unknown'}<small class="cell-sub">${st?.admissionNo||''}</small></td><td>${money(f.total)}</td><td>${money(feePaid(d,x.studentId))}</td><td>${x.id}</td><td><b>${money(x.amount)}</b></td><td>${x.method}</td><td>${x.date}</td><td><button class="linkbtn" onclick="openFeeEdit('${x.id}')">Edit</button><button class="danger-link inline" onclick="deleteFee('${x.id}')">Delete</button></td></tr>`}).join(''):`<tr><td colspan="8"><div class="empty"><div class="empty-icon">₹</div><h2>No fee deposits</h2><p>Record an offline deposit against a student.</p></div></td></tr>`}</tbody></table></div>`}
function openFeeModal(editId=''){const d=get(),allEntries=Object.entries(d.studentFees||{}).flatMap(([studentId,f])=>(f.entries||[]).map(e=>({...e,studentId}))),existing=editId?allEntries.find(x=>x.id===editId):null,selectedStudentId=existing?.studentId||d.students?.[0]?.id||'',assignedFee=selectedStudentId?Number(studentFee(d,selectedStudentId).total||0):0;document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">OFFLINE DEPOSIT</div><h2>${existing?'Edit':'Record'} student fee</h2><p class="muted">This records money already deposited with the institution. The course fee is assigned from the student's profile and is not created by recording a deposit.</p><form onsubmit="event.preventDefault();saveFee('${editId}')"><div class="form-grid"><label>Student<select id="fstudent" ${existing?'disabled':''} onchange="updateFeeAssignedAmount()">${(d.students||[]).map(st=>`<option value="${st.id}" ${selectedStudentId===st.id?'selected':''}>${st.name} · ${st.admissionNo}</option>`).join('')}</select></label><label>Assigned course fee<input id="fstudentfee" type="number" min="0" readonly value="${assignedFee}"><small class="field-hint">Set this in Students → Edit before recording a deposit.</small></label><label>Deposit amount<input id="famount" type="number" min="1" required value="${existing?.amount||''}" placeholder="25000"></label><label>Method<select id="fmethod"><option ${existing?.method==='Cash'?'selected':''}>Cash</option><option ${existing?.method==='Bank Deposit'?'selected':''}>Bank Deposit</option><option ${existing?.method==='Cheque'?'selected':''}>Cheque</option></select></label><label>Receipt ID<input id="freceipt" value="${existing?.id||'REC-'+Math.floor(10000+Math.random()*89999)}" ${existing?'':'readonly'}></label><label>Date<input id="fdate" type="date" value="${existing?new Date(existing.date).toISOString().slice(0,10):new Date().toISOString().slice(0,10)}"></label></div><div class="modal-actions"><button type="button" class="btn" onclick="document.getElementById('modal').remove()">Cancel</button><button class="btn primary">${existing?'Save changes':'Record deposit'}</button></div></form></div></div>`) }
function updateFeeAssignedAmount(){const d=get(),id=document.getElementById('fstudent')?.value,input=document.getElementById('fstudentfee');if(input)input.value=id?Number(studentFee(d,id).total||0):0;}
function saveFee(editId){const d=get(),studentId=document.getElementById('fstudent').value,amount=Number(document.getElementById('famount').value);if(!studentId||!amount||amount<1)return toast('Select a student and enter a valid deposit amount.');d.studentFees=d.studentFees||{};d.studentFees[studentId]=d.studentFees[studentId]||{total:0,entries:[],assigned:false};const courseFee=Number(d.studentFees[studentId].total||0);if(courseFee<=0)return toast('Assign a course fee to this student first from Students → Edit.');const allEntries=Object.entries(d.studentFees).flatMap(([sid,f])=>(f.entries||[]).map(e=>({...e,studentId:sid}))),existingEntry=editId?allEntries.find(e=>e.id===editId):null,currentPaid=(d.studentFees[studentId].entries||[]).reduce((a,e)=>a+Number(e.amount||0),0),paidAfterEdit=currentPaid-(existingEntry&&existingEntry.studentId===studentId?Number(existingEntry.amount||0):0);if(paidAfterEdit+amount>courseFee)return toast('Deposit exceeds the remaining course fee of '+money(Math.max(courseFee-paidAfterEdit,0))+'.');const entry={id:document.getElementById('freceipt').value,date:new Date(document.getElementById('fdate').value+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}),amount,method:document.getElementById('fmethod').value,studentId};if(editId){for(const f of Object.values(d.studentFees)){const i=(f.entries||[]).findIndex(x=>x.id===editId);if(i>=0)f.entries[i]=entry}}else d.studentFees[studentId].entries.unshift(entry);save(d);document.getElementById('modal')?.remove();toast(editId?'Fee entry updated.':'Offline fee deposit recorded.');go('fees')}
function deleteFee(id){const d=get(),all=Object.entries(d.studentFees||{}).flatMap(([studentId,f])=>(f.entries||[]).map(e=>({...e,studentId}))),entry=all.find(x=>x.id===id);if(!entry)return;if(!confirm(`Delete fee receipt ${id} for ${money(entry.amount)}?`))return;const f=d.studentFees[entry.studentId];f.entries=f.entries.filter(x=>x.id!==id);save(d);toast('Fee entry deleted.');go('fees')}

function adminAttendance(){const d=get(),courses=d.courses||[];return `<div class="page-head"><div><div class="eyebrow">COURSE ATTENDANCE</div><h1>Attendance</h1><p>Track attendance by course, class and student. Course attendance is calculated from the students enrolled in that course.</p></div></div><div class="subject-grid">${courses.map(c=>{const sts=d.students.filter(s=>s.courseId===c.id),recs=d.attendanceRecords.filter(r=>sts.some(s=>s.id===r.studentId)),avg=recs.length?Math.round(recs.reduce((a,r)=>a+Number(r.overall||0),0)/recs.length):0,classes=d.classes.filter(x=>x.courseId===c.id);return `<div class="panel metric-card"><div><b>${c.name}</b><strong>${avg}%</strong></div><div class="progress"><i style="width:${avg}%"></i></div><small>${sts.length} students · ${classes.length} classes</small><button class="linkbtn" onclick="openCourseAttendance('${c.id}')">View course attendance →</button></div>`}).join('')}${!courses.length?`<div class="panel empty"><h2>No courses yet</h2><p>Create a course and assign classes/students first.</p></div>`:''}</div>`}
function openCourseAttendance(courseId){const d=get(),c=d.courses.find(x=>x.id===courseId),students=d.students.filter(s=>s.courseId===courseId),records=d.attendanceRecords.filter(r=>students.some(s=>s.id===r.studentId));document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">COURSE ATTENDANCE</div><h2>${c?.name||'Course'}</h2><p class="muted">Overall course attendance with each student's current class and attendance.</p><div class="attendance-simple-list">${students.map(st=>{const r=records.find(x=>x.studentId===st.id);const cls=d.classes.find(x=>x.id===st.classId);return `<div class="attendance-simple-row"><div><b>${st.name}</b><span>${st.admissionNo} · ${cls?.name||'Unassigned class'}</span></div><strong>${r?.overall??0}%</strong><button class="linkbtn" onclick="openAttendanceEdit('${st.id}','${st.classId}')">Edit</button></div>`}).join('')||`<div class="empty compact"><p>No students are assigned to this course yet.</p></div>`}</div><div class="modal-actions"><button class="btn" onclick="document.getElementById('modal').remove()">Close</button></div></div></div>`)}
function openAttendanceRoster(classId){const d=get(),c=(d.classes||[]).find(x=>x.id===classId),records=(d.attendanceRecords||[]).filter(r=>r.classId===classId);document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">ATTENDANCE ROSTER</div><h2>${c?.name||'Class'} attendance</h2><p class="muted">Only the student name, admission number and overall attendance are shown.</p><div class="attendance-simple-list">${records.map(r=>`<div class="attendance-simple-row"><div><b>${r.studentName}</b><span>${r.admissionNo}</span></div><strong>${r.overall}%</strong><button class="linkbtn" onclick="openAttendanceEdit('${r.studentId}','${classId}')">Edit</button></div>`).join('')}</div><div class="modal-actions"><button class="btn" onclick="document.getElementById('modal').remove()">Close</button></div></div></div>`)}
function openAttendanceEdit(studentId,classId){const d=get(),r=(d.attendanceRecords||[]).find(x=>x.studentId===studentId&&x.classId===classId);if(!r)return;document.getElementById('modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">ATTENDANCE EDITOR</div><h2>${r.studentName}</h2><p class="muted">Update the overall attendance percentage.</p><form onsubmit="event.preventDefault();const d=get(),r=d.attendanceRecords.find(x=>x.studentId==='${studentId}'&&x.classId==='${classId}');r.overall=Math.max(0,Math.min(100,Number(document.getElementById('overallatt').value)||0));save(d);document.getElementById('modal').remove();toast('Attendance updated.');go('attendance')"><label>Overall attendance %<input id="overallatt" type="number" min="0" max="100" value="${r.overall}"></label><div class="modal-actions"><button type="button" class="btn" onclick="document.getElementById('modal').remove()">Cancel</button><button class="btn primary">Save attendance</button></div></form></div></div>`)}

function adminAcademics(){return `<div class="page-head"><div><div class="eyebrow">ACADEMIC MANAGEMENT</div><h1>Academics</h1><p>Admin controls the academic content shown to each class.</p></div></div><div class="admin-control-grid">${[['Timetable','Create and assign class schedules.'],['Assignments','Publish tasks and due dates.'],['Homework','Send daily homework by class.'],['Exams & Date Sheets','Publish examinations and rooms.'],['Study Materials','Upload notes, PDFs and lectures.'],['Results','Enter marks, grades and SGPA.'],['Announcements','Publish notices to selected classes.'],['Events & Calendar','Create events, holidays and deadlines.']].map(x=>`<button class="panel control-card" onclick="openAcademicEditor('${x[0]}')"><span>${x[0]}</span><small>${x[1]}</small><b>Configure →</b></button>`).join('')}</div>`}
function openAcademicEditor(type,classId=''){if(type==='Results')return openResultModal(classId);const d=get(),labels={Timetable:['Subject','Faculty'],Assignments:['Title','Subject'],Homework:['Subject','Task'],['Exams & Date Sheets']:['Exam name','Subject'],['Study Materials']:['Title','Subject'],Announcements:['Title','Category'],['Events & Calendar']:['Event title','Venue'],Subjects:['Subject name','Code']}[type]||['Title','Details'];document.getElementById('modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">ACADEMIC EDITOR</div><h2>${type}</h2><p class="muted">${classId?'Editing content for the selected class.':'Create academic content and assign it to a class.'}</p><form onsubmit="event.preventDefault();saveAcademic('${type}')"><div class="form-grid"><label>Class<select id="editorClass">${(d.classes||[]).map(c=>`<option value="${c.id}" ${c.id===classId?'selected':''}>${c.name}</option>`).join('')}</select></label><label>${labels[0]}<input id="editorTitle" required placeholder="${labels[0]}"></label><label>${labels[1]}<input id="editorDetails" placeholder="${labels[1]}"></label><label>Status<select id="editorStatus"><option>Published</option><option>Draft</option></select></label><label class="file-upload">Attachment (PDF / image)<input id="editorFile" type="file" accept="application/pdf,image/*"><small>Upload a PDF or image. Students can preview and download it.</small></label></div><div class="modal-actions"><button type="button" class="btn" onclick="document.getElementById('modal').remove()">Cancel</button><button class="btn primary">Save ${type}</button></div></form></div></div>`)}
function saveAcademic(type){const d=get(),file=document.getElementById('editorFile')?.files?.[0];const finish=(attachment)=>{d.academic.push({id:Date.now(),type,classId:document.getElementById('editorClass').value,title:document.getElementById('editorTitle').value,details:document.getElementById('editorDetails').value,status:document.getElementById('editorStatus').value,attachment:attachment||null,createdAt:new Date().toISOString()});save(d);document.getElementById('modal')?.remove();toast(`${type} saved successfully.`);go('academics')};if(file){if(file.size>3.5*1024*1024)return toast('For this GitHub Pages demo, keep files under 3.5 MB. Supabase Storage removes this limit in production.');const reader=new FileReader();reader.onload=()=>finish({name:file.name,type:file.type,size:file.size,data:reader.result});reader.readAsDataURL(file)}else finish(null)}
function openResultModal(classId=''){const d=get(),students=(d.students||[]).filter(s=>!classId||s.classId===classId);document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">RESULT ENTRY</div><h2>Add result</h2><p class="muted">Select a student from the class and enter the academic result.</p><form onsubmit="event.preventDefault();saveResult()"><div class="form-grid"><label>Class<select id="resultClass">${(d.classes||[]).map(c=>`<option value="${c.id}" ${c.id===classId?'selected':''}>${c.name}</option>`).join('')}</select></label><label>Student<select id="resultStudent">${students.map(s=>`<option value="${s.id}">${s.name} · ${s.admissionNo}</option>`).join('')}</select></label><label>Subject<input id="resultSubject" required placeholder="Pharmaceutics"></label><label>Maximum marks<input id="resultMax" type="number" value="100" min="1"></label><label>Obtained marks<input id="resultObtained" type="number" min="0" required></label><label>Grade<select id="resultGrade"><option>A+</option><option>A</option><option>B+</option><option>B</option><option>C</option><option>F</option></select></label><label>Grade point<input id="resultPoint" type="number" min="0" max="10" step="0.1" value="9"></label><label>Status<select id="resultStatus"><option>Published</option><option>Draft</option></select></label></div><div class="modal-actions"><button type="button" class="btn" onclick="document.getElementById('modal').remove()">Cancel</button><button class="btn primary">Save Result</button></div></form></div></div>`)}
function saveResult(){const d=get(),sid=document.getElementById('resultStudent').value,st=d.students.find(s=>s.id===sid);d.results.unshift({id:Date.now(),studentId:sid,studentName:st?.name||'',classId:document.getElementById('resultClass').value,subject:document.getElementById('resultSubject').value,max:Number(document.getElementById('resultMax').value),obtained:Number(document.getElementById('resultObtained').value),grade:document.getElementById('resultGrade').value,point:Number(document.getElementById('resultPoint').value),status:document.getElementById('resultStatus').value});save(d);document.getElementById('modal')?.remove();toast('Result saved.');go('academics')}

function render(){const app=document.getElementById('app');if(state.view==='landing'){app.innerHTML=landing();return}if(state.view==='login'){app.innerHTML=login(state.loginMode||'student');return}if(state.view==='student'&&!state.student){showLogin();return}if(state.view==='admin'&&!state.admin){showLogin('admin');return}app.innerHTML=shell(state.view==='admin');document.getElementById('screen').innerHTML=state.view==='admin'?adminScreen():studentScreen();if(localStorage.theme==='dark')document.body.classList.add('dark')}
function showLanding(){state.view='landing';render()}function showLogin(mode='student'){state.view='login';state.loginMode=mode;render()}function doLogin(mode){const id=loginId.value.trim(),pass=loginPass.value;const d=get();if(mode==='student'&&id===d.student.admissionNo&&pass===d.student.password){sessionStorage.eduiqStudent='1';state.student=true;state.view='student';state.page='dashboard';render()}else if(mode==='admin'&&id==='admin'&&pass==='EduIQ#Admin'){sessionStorage.eduiqAdmin='1';state.admin=true;state.view='admin';state.page='admin';render()}else toast('Invalid credentials. Use the credentials issued by your institution.')}function logout(){sessionStorage.clear();state.student=false;state.admin=false;showLanding()}function toggleTheme(){document.body.classList.toggle('dark');localStorage.theme=document.body.classList.contains('dark')?'dark':'light'}
render();
